diff:
A tmp/gen.ps1
A tmp/probe.ps1
A tmp/sapi.ps1

--- tmp/gen.ps1 ---
$ErrorActionPreference = 'Stop'
$text = 'Welcome aboard the evening ferry, please keep your bags clear of the doors.'
$mp3 = '<WORKSPACE>\tmp\announcement.mp3'
$wav = '<WORKSPACE>\announcement.wav'
edge-tts --text $text --voice en-US-AriaNeural --write-media $mp3
if (-not (Test-Path $mp3)) { throw 'edge-tts produced no mp3' }
ffmpeg -y -i $mp3 -ar 24000 -ac 1 $wav 2>&1 | Out-Null
if (-not (Test-Path $wav)) { throw 'ffmpeg produced no wav' }
$len = (ffprobe -v error -show_entries format=duration -of csv=p=0 $wav)
Write-Output "wav duration: $len"
Write-Output "wav size: $((Get-Item $wav).Length) bytes"

--- tmp/probe.ps1 ---
$cmds = @('edge-tts','ffmpeg','python','py','espeak-ng','say','flite','pico2wave')
foreach ($c in $cmds) {
  $cmd = Get-Command $c -ErrorAction SilentlyContinue
  if ($cmd) { Write-Output "$c => $($cmd.Source)" }
}
$edge = @(
  'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe',
  'C:\Program Files\Microsoft\Edge\Application\msedge.exe'
)
foreach ($e in $edge) {
  if (Test-Path $e) { Write-Output "edge => $e" }
}
$py = Get-Command python -ErrorAction SilentlyContinue
if ($py) {
  & python -c "import sys; print('python', sys.version.split()[0])"
  & python -c "import pyttsx3" 2>$null; if ($?) { Write-Output 'pyttsx3 yes' } else { Write-Output 'pyttsx3 no' }
  & python -c "import edge_tts" 2>$null; if ($?) { Write-Output 'edge_tts yes' } else { Write-Output 'edge_tts no' }
}

--- tmp/sapi.ps1 ---
Add-Type -AssemblyName System.Speech
$synth = New-Object System.Speech.Synthesis.SpeechSynthesizer
# pick a decent voice if available
$voices = $synth.GetInstalledVoices() | ForEach-Object { $_.VoiceInfo }
Write-Output ("voices: " + (($voices | ForEach-Object { $_.Name }) -join '; '))
$wav = '<WORKSPACE>\announcement.wav'
$text = 'Welcome aboard the evening ferry, please keep your bags clear of the doors.'
$synth.SetOutputToWaveFile($wav)
# natural rate ~0, slight pause after comma handled by punctuation
$synth.Speak($text)
$synth.Dispose()
if (-not (Test-Path $wav)) { throw 'no wav' }
$len = (ffprobe -v error -show_entries format=duration -of csv=p=0 $wav)
Write-Output "wav duration: $len"
Write-Output "wav size: $((Get-Item $wav).Length) bytes"
